def find_components(grid):
    n, m = len(grid), len(grid[0])
    visited = [[False]*m for _ in range(n)]
    components = []

    def bfs(r, c, val):
        comp_cells = []
        queue = [(r,c)]
        visited[r][c] = True
        while queue:
            cr, cc = queue.pop(0)
            comp_cells.append((cr, cc))
            for dr, dc in [(-1,0),(1,0),(0,-1),(0,1)]:
                nr, nc = cr+dr, cc+dc
                if 0<=nr<n and 0<=nc<m and not visited[nr][nc] and grid[nr][nc]==val:
                    visited[nr][nc] = True
                    queue.append((nr, nc))
        return comp_cells

    for r in range(n):
        for c in range(m):
            if grid[r][c] > 0 and not visited[r][c]:
                comp = bfs(r,c, grid[r][c])
                components.append(comp)

    return components

